import sys, math, json, itertools
sys.path.insert(0,'/tmp/exp')
from f32 import f
PI=f(math.pi); sp=f(math.sin(PI)); cp=f(math.cos(PI))
def screen(v,w,h):
    Wp=f(w/2); s=f(min(Wp,h)/2); cx=f(Wp/2); cy=f(h/2)
    x,y,z=v
    m00=f(s*cp); m02=f(s*sp); m11=f(-s)
    px=f(f(f(m00*x)+f(m02*z))+cx)
    py=f(f(m11*y)+cy)
    return (px,py)
def sub(a,b): return f(a-b)
def mul(a,b): return f(a*b)
# edge variants: return function(a,b,p)
def E_pa_ba(a,b,p): return f(mul(sub(p[0],a[0]),sub(b[1],a[1])) - mul(sub(p[1],a[1]),sub(b[0],a[0])))
def E_ba_pa(a,b,p): return f(mul(sub(b[0],a[0]),sub(p[1],a[1])) - mul(sub(b[1],a[1]),sub(p[0],a[0])))
def E_ap_bp(a,b,p): return f(mul(sub(a[0],p[0]),sub(b[1],p[1])) - mul(sub(a[1],p[1]),sub(b[0],p[0])))
def E_bp_ap(a,b,p): return f(mul(sub(b[0],p[0]),sub(a[1],p[1])) - mul(sub(b[1],p[1]),sub(a[0],p[0])))
EDGES={'pa_ba':E_pa_ba,'ba_pa':E_ba_pa,'ap_bp':E_ap_bp,'bp_ap':E_bp_ap}
def cands(V,p):
    out={}
    v0,v1,v2=V
    for en,E in EDGES.items():
        for areaform in ('E012','E120','E201'):
            if areaform=='E012': area=E(v0,v1,v2)
            elif areaform=='E120': area=E(v1,v2,v0)
            else: area=E(v2,v0,v1)
            if area==0: continue
            # pairs for each weight
            for pairs_name,pairs in (('std',((v1,v2),(v2,v0),(v0,v1))),('rev',((v2,v1),(v0,v2),(v1,v0)))):
                e=[E(a,b,p) for a,b in pairs]
                sgn = 1
                ws=[f(x/area) for x in e]
                if pairs_name=='rev': ws=[f(-x) for x in ws]
                # sums
                for order in ((0,1,2),(2,1,0),(0,2,1),(1,2,0)):
                    S=f(f(ws[order[0]]+ws[order[1]])+ws[order[2]])
                    out[(en,areaform,pairs_name,'sum',order)]=S
                # 1 - others
                for k in range(3):
                    o=[i for i in range(3) if i!=k]
                    wk=f(f(1-ws[o[0]])-ws[o[1]])
                    ww=list(ws); ww[k]=wk
                    S=f(f(ww[0]+ww[1])+ww[2])
                    out[(en,areaform,pairs_name,'1m',k)]=S
    return out
def run_search(data, Ivals=(1.0,)):
    res={}
    tot=0
    for e in data:
        V=[screen(v,e['w'],e['h']) for v in e['v']]
        for k,ch in e['pix'].items():
            x,y=map(int,k.split(','))
            p=(f(x//2),f(y))
            o=(ch==' ')
            tot+=1
            for key,S in cands(V,p).items():
                for Iv in Ivals:
                    I=f(S*Iv)
                    kk=key+(Iv,)
                    if (I>=1)!=o: res[kk]=res.get(kk,0)+1
                    else: res.setdefault(kk,0)
    return tot,res
if __name__=='__main__':
    data=json.load(open(sys.argv[1]))
    if len(sys.argv)>2: data=data[:int(sys.argv[2])]
    tot,res=run_search(data,(1.0,f(1-2**-24)))
    print(tot)
    for k,v in sorted(res.items(), key=lambda x:x[1])[:15]: print(k,v)
EOF
