fn probe_ascii<R: Read + Seek>(read: &mut R) -> Result<()> {
    let mut header = String::new();
    let maybe_err = BufReader::new(&mut *read).read_line(&mut header);
    read.seek(SeekFrom::Start(0))?;
    maybe_err?;
    if !header.starts_with("solid ") {
        Err(Error::new(
            ErrorKind::InvalidData,
            "ascii STL does not start with \"solid \"",
        ))
    } else {
        Ok(())
    }
}

struct AsciiReader<R: BufRead> {
    lines: std::io::Lines<R>,
}

impl<R: BufRead> AsciiReader<R> {
    fn next_tokens(&mut self) -> Option<Result<Vec<String>>> {
        loop {
            match self.lines.next() {
                None => return None,
                Some(Err(e)) => return Some(Err(e)),
                Some(Ok(l)) => {
                    let toks: Vec<String> =
                        l.trim().split_whitespace().map(|t| t.to_string()).collect();
                    if toks.is_empty() {
                        continue;
                    }
                    return Some(Ok(toks));
                }
            }
        }
    }

    fn tokens_to_f32(tokens: &[String], out: &mut [f32]) -> Result<()> {
        for i in 0..tokens.len() {
            let f = tokens[i]
                .parse::<f32>()
                .map_err(|e| Error::new(ErrorKind::InvalidData, e.to_string()))?;
            if !f.is_finite() {
                return Err(Error::new(
                    ErrorKind::InvalidData,
                    format!("expected finite f32, got {} which is {:?}", f, f.classify()),
                ));
            }
            out[i] = f;
        }
        Ok(())
    }

    fn expect_static(&mut self, expectation: &[&str]) -> Result<()> {
        if let Some(line) = self.next_tokens() {
            let line = line?;
            if line != expectation {
                return Err(Error::new(
                    ErrorKind::InvalidData,
                    format!("expected {:?}, got {:?}", expectation, line),
                ));
            }
        } else {
            return Err(Error::new(
                ErrorKind::UnexpectedEof,
                format!("EOF while expecting {:?}", expectation),
            ));
        }
        Ok(())
    }

    fn next_face(&mut self) -> Result<Option<StlTriangle>> {
        let header = match self.next_tokens() {
            None => {
                return Err(Error::new(
                    ErrorKind::UnexpectedEof,
                    "EOF while expecting facet or endsolid.",
                ))
            }
            Some(h) => h?,
        };
        if !header.is_empty() && header[0] == "endsolid" {
            return Ok(None);
        }
        if header.len() != 5 || header[0] != "facet" || header[1] != "normal" {
            return Err(Error::new(
                ErrorKind::InvalidData,
                format!("invalid facet header: {:?}", header),
            ));
        }
        let mut normal = [0f32; 3];
        Self::tokens_to_f32(&header[2..5], &mut normal)?;
        self.expect_static(&["outer", "loop"])?;
        let mut verts = [[0f32; 3]; 3];
        for v in verts.iter_mut() {
            if let Some(line) = self.next_tokens() {
                let line = line?;
                if line.len() != 4 || line[0] != "vertex" {
                    return Err(Error::new(
                        ErrorKind::InvalidData,
                        format!("vertex f32 f32 f32, got {:?}", line),
                    ));
                }
                Self::tokens_to_f32(&line[1..4], &mut v[..])?;
            } else {
                return Err(Error::new(
                    ErrorKind::UnexpectedEof,
                    "EOF while expecting vertex",
                ));
            }
        }
        self.expect_static(&["endloop"])?;
        self.expect_static(&["endfacet"])?;
        Ok(Some(StlTriangle { vertices: verts }))
    }
}

fn read_u32<R: Read>(r: &mut R) -> Result<u32> {
    let mut b = [0u8; 4];
    r.read_exact(&mut b)?;
    Ok(u32::from_le_bytes(b))
}

fn read_f32<R: Read>(r: &mut R) -> Result<f32> {
    let mut b = [0u8; 4];
    r.read_exact(&mut b)?;
    Ok(f32::from_le_bytes(b))
}

fn read_u16<R: Read>(r: &mut R) -> Result<u16> {
    let mut b = [0u8; 2];
    r.read_exact(&mut b)?;
    Ok(u16::from_le_bytes(b))
}

struct Indexer {
    vertices: Vec<[f32; 3]>,
    faces: Vec<[usize; 3]>,
    map: HashMap<[u32; 3], usize>,
}

impl Indexer {
    fn new() -> Self {
        Indexer {
            vertices: Vec::new(),
            faces: Vec::new(),
            map: HashMap::new(),
        }
    }
    fn push(&mut self, t: StlTriangle) {
        let mut idx = [0usize; 3];
        for (i, v) in t.vertices.iter().enumerate() {
            let key = [v[0].to_bits(), v[1].to_bits(), v[2].to_bits()];
            let next = self.vertices.len();
            let index = *self.map.entry(key).or_insert(next);
            if index == next {
                self.vertices.push(*v);
            }
            idx[i] = index;
        }
        self.faces.push(idx);
    }
    fn finish(self) -> IndexedMesh {
        IndexedMesh {
            vertices: self.vertices,
            faces: self.faces,
        }
    }
}

pub fn read_stl<R: Read + Seek>(read: &mut R) -> Result<IndexedMesh> {
    let mut indexer = Indexer::new();
    match probe_ascii(read) {
        Ok(()) => {
            let mut lines = BufReader::new(read).lines();
            match lines.next() {
                Some(Err(e)) => return Err(e),
                Some(Ok(ref line)) if !line.starts_with("solid ") => {
                    return Err(Error::new(
                        ErrorKind::InvalidData,
                        "ascii STL does not start with \"solid \"",
                    ))
                }
                None => return Err(Error::new(ErrorKind::UnexpectedEof, "empty file?")),
                _ => {}
            }
            let mut reader = AsciiReader { lines };
            loop {
                match reader.next_face()? {
                    None => break,
                    Some(t) => indexer.push(t),
                }
            }
        }
        Err(_) => {
            let mut reader = BufReader::new(read);
            let mut header = [0u8; 80];
            reader.read_exact(&mut header)?;
            let count = read_u32(&mut reader)? as usize;
            for _ in 0..count {
                let mut normal = [0f32; 3];
                for n in normal.iter_mut() {
                    *n = read_f32(&mut reader)?;
                }
                let mut verts = [[0f32; 3]; 3];
                for v in verts.iter_mut() {
                    for c in v.iter_mut() {
                        *c = read_f32(&mut reader)?;
                    }
                }
                read_u16(&mut reader)?;
                indexer.push(StlTriangle { vertices: verts });
            }
        }
    }
    Ok(indexer.finish())
}
