// A small Wavefront OBJ/MTL reader that mimics the behaviour of the tobj
// crate (single index mode, triangulation, points and lines ignored).

use std::collections::HashMap;
use std::fmt;
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

pub const MISSING_INDEX: usize = usize::MAX;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadError {
    OpenFileFailed,
    ReadError,
    UnrecognizedCharacter,
    PositionParseError,
    NormalParseError,
    TexcoordParseError,
    FaceParseError,
    MaterialParseError,
    InvalidObjectName,
    InvalidPolygon,
    FaceVertexOutOfBounds,
    FaceTexCoordOutOfBounds,
    FaceNormalOutOfBounds,
    FaceColorOutOfBounds,
    InvalidLoadOptionConfig,
    GenericFailure,
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let msg = match *self {
            LoadError::OpenFileFailed => "open file failed",
            LoadError::ReadError => "read error",
            LoadError::UnrecognizedCharacter => "unrecognized character",
            LoadError::PositionParseError => "position parse error",
            LoadError::NormalParseError => "normal parse error",
            LoadError::TexcoordParseError => "texcoord parse error",
            LoadError::FaceParseError => "face parse error",
            LoadError::MaterialParseError => "material parse error",
            LoadError::InvalidObjectName => "invalid object name",
            LoadError::InvalidPolygon => "invalid polygon",
            LoadError::FaceVertexOutOfBounds => "face vertex index out of bounds",
            LoadError::FaceTexCoordOutOfBounds => "face texcoord index out of bounds",
            LoadError::FaceNormalOutOfBounds => "face normal index out of bounds",
            LoadError::FaceColorOutOfBounds => "face vertex color index out of bounds",
            LoadError::InvalidLoadOptionConfig => "invalid load option config",
            LoadError::GenericFailure => "generic failure",
        };
        f.write_str(msg)
    }
}

#[derive(Debug, Clone, Default)]
pub struct Material {
    pub name: String,
    pub diffuse: [f32; 3],
}

#[derive(Debug, Clone, Default)]
pub struct Mesh {
    pub positions: Vec<f32>,
    pub indices: Vec<u32>,
    pub material_id: Option<usize>,
}

#[derive(Debug, Clone)]
pub struct Model {
    pub mesh: Mesh,
    pub name: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
struct VertexIndices {
    v: usize,
    vt: usize,
    vn: usize,
}

#[derive(Debug, Clone)]
enum Face {
    Point,
    Line,
    Triangle(VertexIndices, VertexIndices, VertexIndices),
    Quad(VertexIndices, VertexIndices, VertexIndices, VertexIndices),
    Polygon(Vec<VertexIndices>),
}

/// Information about a panic that the original library would raise.
pub struct LibPanic {
    pub line: u32,
    pub col: u32,
    pub msg: String,
}

fn lib_panic(line: u32, col: u32, msg: String) -> ! {
    std::panic::panic_any(LibPanic { line, col, msg })
}

fn parse_vertex_indices(
    face_str: &str,
    pos_sz: usize,
    tex_sz: usize,
    norm_sz: usize,
) -> Option<VertexIndices> {
    let mut indices = [MISSING_INDEX; 3];
    for (i, part) in face_str.split('/').enumerate() {
        if !part.is_empty() {
            match part.parse::<isize>() {
                Ok(x) => {
                    let value = if x < 0 {
                        match i {
                            0 => (pos_sz as isize + x) as usize,
                            1 => (tex_sz as isize + x) as usize,
                            2 => (norm_sz as isize + x) as usize,
                            _ => lib_panic(
                                738,
                                38,
                                "Invalid number of elements for a face (> 3)!".to_string(),
                            ),
                        }
                    } else {
                        (x - 1) as usize
                    };
                    if i >= 3 {
                        lib_panic(
                            733,
                            25,
                            format!(
                                "index out of bounds: the len is 3 but the index is {}",
                                i
                            ),
                        );
                    }
                    indices[i] = value;
                }
                Err(_) => return None,
            }
        }
    }
    Some(VertexIndices {
        v: indices[0],
        vt: indices[1],
        vn: indices[2],
    })
}

fn parse_face<'a, I: Iterator<Item = &'a str>>(
    words: I,
    faces: &mut Vec<Face>,
    pos_sz: usize,
    tex_sz: usize,
    norm_sz: usize,
) -> bool {
    let mut indices = Vec::new();
    for w in words {
        match parse_vertex_indices(w, pos_sz, tex_sz, norm_sz) {
            Some(v) => indices.push(v),
            None => return false,
        }
    }
    match indices.len() {
        1 => faces.push(Face::Point),
        2 => faces.push(Face::Line),
        3 => faces.push(Face::Triangle(indices[0], indices[1], indices[2])),
        4 => faces.push(Face::Quad(indices[0], indices[1], indices[2], indices[3])),
        _ => faces.push(Face::Polygon(indices)),
    }
    true
}

fn parse_floatn<'a, I: Iterator<Item = &'a str>>(words: &mut I, vals: &mut Vec<f32>, n: usize) -> bool {
    let sz = vals.len();
    for p in words.take(n) {
        match p.parse::<f32>() {
            Ok(x) => vals.push(x),
            Err(_) => return false,
        }
    }
    sz + n == vals.len()
}

fn add_vertex(
    mesh: &mut Mesh,
    index_map: &mut HashMap<VertexIndices, u32>,
    vert: &VertexIndices,
    pos: &[f32],
    v_color: &[f32],
    texcoord: &[f32],
    normal: &[f32],
) -> Result<(), LoadError> {
    match index_map.get(vert) {
        Some(&i) => mesh.indices.push(i),
        None => {
            let v = vert.v;
            if v.saturating_mul(3).saturating_add(2) >= pos.len() {
                return Err(LoadError::FaceVertexOutOfBounds);
            }
            mesh.positions.push(pos[v * 3]);
            mesh.positions.push(pos[v * 3 + 1]);
            mesh.positions.push(pos[v * 3 + 2]);
            if !texcoord.is_empty() && vert.vt != MISSING_INDEX {
                let vt = vert.vt;
                if vt.saturating_mul(2).saturating_add(1) >= texcoord.len() {
                    return Err(LoadError::FaceTexCoordOutOfBounds);
                }
            }
            if !normal.is_empty() && vert.vn != MISSING_INDEX {
                let vn = vert.vn;
                if vn.saturating_mul(3).saturating_add(2) >= normal.len() {
                    return Err(LoadError::FaceNormalOutOfBounds);
                }
            }
            if !v_color.is_empty() {
                if v.saturating_mul(3).saturating_add(2) >= v_color.len() {
                    return Err(LoadError::FaceColorOutOfBounds);
                }
            }
            let next = index_map.len() as u32;
            mesh.indices.push(next);
            index_map.insert(*vert, next);
        }
    }
    Ok(())
}

fn export_faces(
    pos: &[f32],
    v_color: &[f32],
    texcoord: &[f32],
    normal: &[f32],
    faces: &[Face],
    mat_id: Option<usize>,
) -> Result<Mesh, LoadError> {
    let mut index_map = HashMap::new();
    let mut mesh = Mesh {
        material_id: mat_id,
        ..Default::default()
    };
    for face in faces {
        match face {
            Face::Point | Face::Line => {}
            Face::Triangle(a, b, c) => {
                add_vertex(&mut mesh, &mut index_map, a, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, b, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, c, pos, v_color, texcoord, normal)?;
            }
            Face::Quad(a, b, c, d) => {
                add_vertex(&mut mesh, &mut index_map, a, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, b, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, c, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, a, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, c, pos, v_color, texcoord, normal)?;
                add_vertex(&mut mesh, &mut index_map, d, pos, v_color, texcoord, normal)?;
            }
            Face::Polygon(indices) => {
                if indices.is_empty() {
                    lib_panic(
                        949,
                        37,
                        "index out of bounds: the len is 0 but the index is 0".to_string(),
                    );
                }
                let a = indices[0];
                let mut b = indices[1];
                for c in indices.iter().skip(2) {
                    add_vertex(&mut mesh, &mut index_map, &a, pos, v_color, texcoord, normal)?;
                    add_vertex(&mut mesh, &mut index_map, &b, pos, v_color, texcoord, normal)?;
                    add_vertex(&mut mesh, &mut index_map, c, pos, v_color, texcoord, normal)?;
                    b = *c;
                }
            }
        }
    }
    Ok(mesh)
}

pub type MtlResult = Result<(Vec<Material>, HashMap<String, usize>), LoadError>;

fn parse_float3<'a, I: Iterator<Item = &'a str>>(words: I, vals: &mut [f32; 3]) -> Result<(), LoadError> {
    for (i, p) in words.enumerate().take(3) {
        match p.parse::<f32>() {
            Ok(x) => vals[i] = x,
            Err(_) => return Err(LoadError::MaterialParseError),
        }
    }
    Ok(())
}

fn parse_float(val: Option<&str>) -> Result<f32, LoadError> {
    match val {
        Some(v) => v.parse::<f32>().map_err(|_| LoadError::MaterialParseError),
        None => Err(LoadError::MaterialParseError),
    }
}

pub fn load_mtl_buf<B: BufRead>(reader: &mut B) -> MtlResult {
    let mut materials = Vec::new();
    let mut mat_map = HashMap::new();
    let mut cur_mat = Material::default();
    let mut ambient = [0f32; 3];
    let mut specular = [0f32; 3];
    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => return Err(LoadError::ReadError),
        };
        let trimmed = line.trim();
        let mut words = line.split_whitespace();
        match words.next() {
            Some("#") | None => continue,
            Some("newmtl") => {
                if !cur_mat.name.is_empty() {
                    mat_map.insert(cur_mat.name.clone(), materials.len());
                    materials.push(cur_mat);
                }
                cur_mat = Material::default();
                cur_mat.name = trimmed[6..].trim().to_owned();
                if cur_mat.name.is_empty() {
                    return Err(LoadError::InvalidObjectName);
                }
            }
            Some("Ka") => parse_float3(words, &mut ambient)?,
            Some("Kd") => parse_float3(words, &mut cur_mat.diffuse)?,
            Some("Ks") => parse_float3(words, &mut specular)?,
            Some("Ns") | Some("Ni") | Some("d") => {
                parse_float(words.next())?;
            }
            Some("map_Ka") | Some("map_Kd") | Some("map_Ks") | Some("map_Bump")
            | Some("map_bump") | Some("map_Ns") | Some("map_ns") | Some("map_NS")
            | Some("bump") | Some("map_d") => {
                let key_len = match trimmed.split_whitespace().next() {
                    Some(k) => k.len(),
                    None => 0,
                };
                match trimmed.get(key_len..).map(str::trim) {
                    Some("") | None => return Err(LoadError::MaterialParseError),
                    Some(_) => {}
                }
            }
            Some("illum") => {
                if let Some(p) = words.next() {
                    if p.parse::<u8>().is_err() {
                        return Err(LoadError::MaterialParseError);
                    }
                } else {
                    return Err(LoadError::MaterialParseError);
                }
            }
            Some(_) => {}
        }
    }
    if !cur_mat.name.is_empty() {
        mat_map.insert(cur_mat.name.clone(), materials.len());
        materials.push(cur_mat);
    }
    Ok((materials, mat_map))
}

pub fn load_mtl(path: &Path) -> MtlResult {
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return Err(LoadError::OpenFileFailed),
    };
    let mut reader = BufReader::new(file);
    load_mtl_buf(&mut reader)
}

pub type LoadResult = Result<(Vec<Model>, Result<Vec<Material>, LoadError>), LoadError>;

pub fn load_obj_buf<B: BufRead, ML: Fn(&Path) -> MtlResult>(
    reader: &mut B,
    material_loader: ML,
) -> LoadResult {
    let mut models = Vec::new();
    let mut materials: Vec<Material> = Vec::new();
    let mut mat_map: HashMap<String, usize> = HashMap::new();

    let mut tmp_pos = Vec::new();
    let mut tmp_v_color = Vec::new();
    let mut tmp_texcoord = Vec::new();
    let mut tmp_normal = Vec::new();
    let mut tmp_faces: Vec<Face> = Vec::new();
    let mut name = "unnamed_object".to_owned();
    let mut mat_id: Option<usize> = None;
    let mut mtlresult: Result<(), LoadError> = Ok(());

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => return Err(LoadError::ReadError),
        };
        let line = &line[..];
        let mut words = line.split_whitespace();
        match words.next() {
            Some("#") | None => continue,
            Some("v") => {
                if !parse_floatn(&mut words, &mut tmp_pos, 3) {
                    return Err(LoadError::PositionParseError);
                }
                parse_floatn(&mut words, &mut tmp_v_color, 3);
            }
            Some("vt") => {
                if !parse_floatn(&mut words, &mut tmp_texcoord, 2) {
                    return Err(LoadError::TexcoordParseError);
                }
            }
            Some("vn") => {
                if !parse_floatn(&mut words, &mut tmp_normal, 3) {
                    return Err(LoadError::NormalParseError);
                }
            }
            Some("f") | Some("l") => {
                if !parse_face(
                    words,
                    &mut tmp_faces,
                    tmp_pos.len() / 3,
                    tmp_texcoord.len() / 2,
                    tmp_normal.len() / 3,
                ) {
                    return Err(LoadError::FaceParseError);
                }
            }
            Some("o") | Some("g") => {
                if !tmp_faces.is_empty() {
                    models.push(Model {
                        mesh: export_faces(
                            &tmp_pos,
                            &tmp_v_color,
                            &tmp_texcoord,
                            &tmp_normal,
                            &tmp_faces,
                            mat_id,
                        )?,
                        name: name.clone(),
                    });
                    tmp_faces.clear();
                }
                let size = line.chars().next().map(|c| c.len_utf8()).unwrap_or(1);
                name = line[size..].trim().to_owned();
                if name.is_empty() {
                    name = "unnamed_object".to_owned();
                }
            }
            Some("mtllib") => {
                if let Some(mtllib) = words.next() {
                    let mat_file = Path::new(mtllib).to_path_buf();
                    match material_loader(mat_file.as_path()) {
                        Ok((mut mats, map)) => {
                            let mat_offset = materials.len();
                            for m in map {
                                mat_map.insert(m.0, m.1 + mat_offset);
                            }
                            materials.append(&mut mats);
                        }
                        Err(e) => {
                            mtlresult = Err(e);
                        }
                    }
                } else {
                    return Err(LoadError::MaterialParseError);
                }
            }
            Some("usemtl") => {
                let mat_name = line.get(6..).unwrap_or("").trim().to_owned();
                if !mat_name.is_empty() {
                    let new_mat = mat_map.get(&mat_name).cloned();
                    if mat_id != new_mat && !tmp_faces.is_empty() {
                        models.push(Model {
                            mesh: export_faces(
                                &tmp_pos,
                                &tmp_v_color,
                                &tmp_texcoord,
                                &tmp_normal,
                                &tmp_faces,
                                mat_id,
                            )?,
                            name: name.clone(),
                        });
                        tmp_faces.clear();
                    }
                    mat_id = new_mat;
                } else {
                    return Err(LoadError::MaterialParseError);
                }
            }
            Some(_) => {}
        }
    }

    models.push(Model {
        mesh: export_faces(
            &tmp_pos,
            &tmp_v_color,
            &tmp_texcoord,
            &tmp_normal,
            &tmp_faces,
            mat_id,
        )?,
        name,
    });

    Ok((models, mtlresult.map(|_| materials)))
}

pub fn load_obj(file_name: &str) -> LoadResult {
    let file = match File::open(file_name) {
        Ok(f) => f,
        Err(_) => return Err(LoadError::OpenFileFailed),
    };
    let mut reader = BufReader::new(file);
    let path = Path::new(file_name);
    load_obj_buf(&mut reader, |mat_path| {
        let full_path = if let Some(parent) = path.parent() {
            parent.join(mat_path)
        } else {
            mat_path.to_owned()
        };
        load_mtl(&full_path)
    })
}
