use crate::geometry::SimpleMesh;

pub const RAMP: [char; 10] = [' ', '.', ':', '-', '=', '+', '*', '#', '%', '@'];

#[derive(Clone, Copy, PartialEq)]
pub struct Cell {
    pub ch: char,
    pub color: [u8; 3],
}

pub const BLANK: Cell = Cell {
    ch: ' ',
    color: [0, 0, 0],
};

pub struct Frame {
    pub width: usize,
    pub height: usize,
    pub image_mode: bool,
    pub cells: Vec<Cell>,
    pub zbuf: Vec<f32>,
}

impl Frame {
    pub fn new(width: usize, height: usize, image_mode: bool) -> Frame {
        let len = if image_mode {
            (width + 1) * height
        } else {
            width * height
        };
        Frame {
            width,
            height,
            image_mode,
            cells: vec![BLANK; len],
            zbuf: vec![f32::MAX; len],
        }
    }
}

type M4 = [[f32; 4]; 4];

fn euler(roll: f32, pitch: f32, yaw: f32) -> [[f32; 3]; 3] {
    let (sr, cr) = roll.sin_cos();
    let (sp, cp) = pitch.sin_cos();
    let (sy, cy) = yaw.sin_cos();
    [
        [cy * cp, cy * sp * sr - sy * cr, cy * sp * cr + sy * sr],
        [sy * cp, sy * sp * sr + cy * cr, sy * sp * cr - cy * sr],
        [-sp, cp * sr, cp * cr],
    ]
}

fn mat_mul(a: &M4, b: &M4) -> M4 {
    let mut c = [[0f32; 4]; 4];
    for i in 0..4 {
        for j in 0..4 {
            let mut acc = a[i][0] * b[0][j];
            for k in 1..4 {
                acc = acc + a[i][k] * b[k][j];
            }
            c[i][j] = acc;
        }
    }
    c
}

fn transform(m: &M4, v: &[f32; 3]) -> [f32; 3] {
    let mut out = [0f32; 3];
    for i in 0..3 {
        out[i] = m[i][0] * v[0] + m[i][1] * v[1] + m[i][2] * v[2] + m[i][3];
    }
    out
}

fn rot3(r: &[[f32; 3]; 3], v: &[f32; 3]) -> [f32; 3] {
    let mut out = [0f32; 3];
    for i in 0..3 {
        out[i] = r[i][0] * v[0] + r[i][1] * v[1] + r[i][2] * v[2];
    }
    out
}

fn sub(a: &[f32; 3], b: &[f32; 3]) -> [f32; 3] {
    [a[0] - b[0], a[1] - b[1], a[2] - b[2]]
}

fn cross(a: &[f32; 3], b: &[f32; 3]) -> [f32; 3] {
    [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    ]
}

fn normalize(a: &[f32; 3]) -> [f32; 3] {
    let n = (a[0] * a[0] + a[1] * a[1] + a[2] * a[2]).sqrt();
    [a[0] / n, a[1] / n, a[2] / n]
}

#[inline]
fn edge(a: &[f32; 3], b: &[f32; 3], p: &[f32; 2]) -> f32 {
    (p[0] - a[0]) * (b[1] - a[1]) - (p[1] - a[1]) * (b[0] - a[0])
}

pub fn shade_char(intensity: f32) -> char {
    let x = intensity * 10.0;
    let idx = x as usize;
    if idx >= RAMP.len() {
