    } else if idx <= 1 {
        '.'
    } else {
        RAMP[idx]
    }
}

pub fn scale_factor(meshes: &[SimpleMesh]) -> f32 {
    let mut max = 0f32;
    for m in meshes {
        for t in &m.triangles {
            for v in &t.v {
                max = max.max(v[0]).max(v[1]).max(v[2]);
            }
        }
    }
    1.0 / max
}

pub fn render(meshes: &[SimpleMesh], frame: &mut Frame, rx: f32, ry: f32, rz: f32) {
    let w = frame.width;
    let h = frame.height;
    let wf = w as f32;
    let hf = h as f32;
    let half_w = wf / 2.0;
    let s = half_w.min(hf) / 2.0;
    let cx = half_w / 2.0;
    let cy = hf / 2.0;
    let k = scale_factor(meshes);
