        for tri in &mesh.triangles {
            let mv = [
                [tri.v[0][0] * k, tri.v[0][1] * k, tri.v[0][2] * k],
                [tri.v[1][0] * k, tri.v[1][1] * k, tri.v[1][2] * k],
                [tri.v[2][0] * k, tri.v[2][1] * k, tri.v[2][2] * k],
