// Command line parsing that mirrors the behaviour (and messages) of the
// clap 2.x based interface of the original program.

use std::collections::HashMap;

#[derive(Clone)]
pub struct FlagDef {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
}

#[derive(Clone)]
pub struct OptDef {
    pub name: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub value_name: &'static str,
    pub required: bool,
}

#[derive(Clone)]
pub struct PosDef {
    pub name: &'static str,
    pub required: bool,
    pub multiple: bool,
}

#[derive(Clone)]
pub struct AppDef {
    pub name: &'static str,
    pub version: &'static str,
    pub flags: Vec<FlagDef>,
    pub opts: Vec<OptDef>,
    pub positionals: Vec<PosDef>,
    pub subcommands: Vec<AppDef>,
    pub help_short: bool,
    /// Text of the help body (everything after the USAGE line).
    pub help_header: String,
    pub help_body: String,
    // runtime
    pub bin_name: String,
    pub usage: Option<String>,
}

#[derive(Default, Debug, Clone)]
pub struct ArgMatch {
    pub occurs: usize,
    pub vals: Vec<String>,
}

#[derive(Default, Debug, Clone)]
pub struct Matches {
    pub args: HashMap<String, ArgMatch>,
    pub order: Vec<String>,
    pub subcommand: Option<(String, Box<Matches>)>,
}

impl Matches {
    fn contains(&self, name: &str) -> bool {
        self.args.contains_key(name)
    }
    fn entry(&mut self, name: &str) -> &mut ArgMatch {
        if !self.args.contains_key(name) {
            self.order.push(name.to_string());
        }
        self.args.entry(name.to_string()).or_default()
    }
    fn inc(&mut self, name: &str) {
        self.entry(name).occurs += 1;
    }
    fn insert(&mut self, name: &str) {
        self.entry(name);
    }
    fn add_val(&mut self, name: &str, val: &str) {
        self.entry(name).vals.push(val.to_string());
    }
    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.args
            .get(name)
            .and_then(|m| m.vals.first())
            .map(|s| s.as_str())
    }
    pub fn is_present(&self, name: &str) -> bool {
        self.args.contains_key(name)
    }
    pub fn subcommand_matches(&self, name: &str) -> Option<&Matches> {
        match &self.subcommand {
            Some((n, m)) if n == name => Some(m),
            _ => None,
        }
    }
}

pub enum ClapError {
    Help(String),
    Version(String),
    Error(String),
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum ParseResult {
    Flag,
    Opt(usize),
    ValuesDone,
    NotFound,
}

const GOOD: &str = "\x1b[32m";
const RESET: &str = "\x1b[0m";

fn good(s: &str) -> String {
    format!("{}{}{}", GOOD, s, RESET)
}

pub fn jaro(a: &str, b: &str) -> f64 {
    if a == b {
        return 1.0;
    }
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_char) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for j in 0..=max_bound {
            let b_char = &b_chars[j];
            if min_bound <= j && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|&(x, y)| x == y)
        .count();
    let d = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean<'a, I: IntoIterator<Item = &'a str>>(v: &str, possible: I) -> Option<&'a str> {
    let mut candidate: Option<(f64, &str)> = None;
    for pv in possible {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

impl AppDef {
    fn find_flag_short(&self, c: char) -> Option<usize> {
        self.flags.iter().position(|f| f.short == Some(c))
    }
    fn find_flag_long(&self, l: &str) -> Option<usize> {
        self.flags.iter().position(|f| f.long == Some(l))
    }
    fn find_opt_short(&self, c: char) -> Option<usize> {
        self.opts.iter().position(|o| o.short == Some(c))
    }
    fn find_opt_long(&self, l: &str) -> Option<usize> {
        self.opts.iter().position(|o| o.long == Some(l))
    }

    fn display_name(&self) -> String {
        if self.bin_name.contains(' ') {
            self.bin_name.replace(' ', "-")
        } else {
            self.name.to_string()
        }
    }

    fn usage_name(&self) -> String {
        match &self.usage {
            Some(u) => u.clone(),
            None => self.bin_name.clone(),
        }
    }

    fn arg_display(&self, name: &str) -> Option<String> {
        if let Some(p) = self.positionals.iter().find(|p| p.name == name) {
            return Some(format!("<{}>{}", p.name, if p.multiple { "..." } else { "" }));
        }
        if let Some(f) = self.flags.iter().find(|f| f.name == name) {
            return Some(match f.long {
                Some(l) => format!("--{}", l),
                None => format!("-{}", f.short.unwrap()),
            });
        }
        if let Some(o) = self.opts.iter().find(|o| o.name == name) {
            let head = match o.long {
                Some(l) => format!("--{}", l),
                None => format!("-{}", o.short.unwrap()),
            };
            return Some(format!("{} <{}>", head, o.value_name));
        }
        None
    }

    fn required_names(&self) -> Vec<&'static str> {
        let mut v = Vec::new();
        for p in &self.positionals {
            if p.required {
                v.push(p.name);
            }
        }
        for o in &self.opts {
            if o.required {
                v.push(o.name);
            }
        }
        v
    }

    /// clap's get_required_usage_from
    fn required_usage_from(&self, reqs: &[String], matcher: Option<&Matches>) -> Vec<String> {
        let mut desc: Vec<String> = reqs.to_vec();
        desc.sort();
        desc.dedup();
        let mut out = Vec::new();
        // positionals, by index
        for (_, p) in self.positionals.iter().enumerate() {
            if desc.iter().any(|d| d == p.name) {
                if let Some(m) = matcher {
                    if m.contains(p.name) {
                        continue;
                    }
                }
                out.push(self.arg_display(p.name).unwrap());
            }
        }
        for d in &desc {
            if self.positionals.iter().any(|p| p.name == d) {
                continue;
            }
            if let Some(m) = matcher {
                if m.contains(d) {
                    continue;
                }
            }
            if let Some(s) = self.arg_display(d) {
                out.push(s);
            }
        }
        out
    }

    fn help_usage(&self) -> String {
        let mut usage = self.usage_name();
        if !self.flags.is_empty() {
            usage.push_str(" [FLAGS]");
        }
        if self.opts.iter().any(|o| !o.required) {
            usage.push_str(" [OPTIONS]");
        }
        let reqs: Vec<String> = self.required_names().iter().map(|s| s.to_string()).collect();
        for s in self.required_usage_from(&reqs, None) {
            usage.push(' ');
            usage.push_str(&s);
        }
        for p in &self.positionals {
            if !p.required {
                usage.push_str(&format!(" [{}]{}", p.name, if p.multiple { "..." } else { "" }));
            }
        }
        if !self.subcommands.is_empty() {
            usage.push_str(" [SUBCOMMAND]");
        }
        usage
    }

    fn smart_usage(&self, used: &[String]) -> String {
        let mut hs: Vec<String> = self.required_names().iter().map(|s| s.to_string()).collect();
        hs.extend(used.iter().cloned());
        let mut usage = self.usage_name();
        for s in self.required_usage_from(&hs, None) {
            usage.push(' ');
            usage.push_str(&s);
        }
        usage
    }

    fn error_usage(&self, matcher: &Matches) -> String {
        let mut used = Vec::new();
        for n in &matcher.order {
            if let Some(o) = self.opts.iter().find(|o| o.name == n) {
                if !o.required {
                    used.push(n.clone());
                }
            } else if self.positionals.iter().any(|p| p.name == n) {
                // required or visible positionals are not part of the usage
            } else {
                used.push(n.clone());
            }
        }
        let body = if used.is_empty() {
            self.help_usage()
        } else {
            self.smart_usage(&used)
        };
        format!("USAGE:\n    {}", body)
    }

    fn help_text(&self) -> String {
        format!(
            "{} {}\n{}USAGE:\n    {}\n\n{}",
            self.display_name(),
            self.version,
            self.help_header,
            self.help_usage(),
            self.help_body
        )
    }

    fn version_text(&self) -> String {
        format!("{} {}\n", self.display_name(), self.version)
    }

    fn sc_names(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = self.subcommands.iter().map(|s| s.name).collect();
        if !self.subcommands.is_empty() {
            v.push("help");
        }
        v
    }

    fn unknown_argument(&self, arg: &str, suffix: &str, matcher: &Matches) -> ClapError {
        ClapError::Error(format!(
            "error: Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try --help\n",
            arg,
            suffix,
            self.error_usage(matcher)
        ))
    }

    fn parse_opt(
        &self,
        val: Option<&str>,
        oi: usize,
        matcher: &mut Matches,
    ) -> Result<ParseResult, ClapError> {
        let name = self.opts[oi].name;
        if let Some(fv) = val {
            let v = fv.trim_start_matches('=');
            matcher.add_val(name, v);
        }
        matcher.inc(name);
        if val.is_none() {
            return Ok(ParseResult::Opt(oi));
        }
        Ok(ParseResult::ValuesDone)
    }

    fn check_help_version_long(&self, arg: &str) -> Result<(), ClapError> {
        if arg == "help" {
            return Err(ClapError::Help(self.help_text()));
        }
        if arg == "version" {
            return Err(ClapError::Version(self.version_text()));
        }
        Ok(())
    }

    fn parse_long_arg(
        &self,
        matcher: &mut Matches,
        full_arg: &str,
        rest: &[String],
    ) -> Result<ParseResult, ClapError> {
        let trimmed = full_arg.trim_start_matches('-');
        let (arg, val) = match trimmed.find('=') {
            Some(i) => (&trimmed[..i], Some(&trimmed[i..])),
            None => (trimmed, None),
        };
        if let Some(oi) = self.find_opt_long(arg) {
            return self.parse_opt(val, oi, matcher);
        } else if let Some(fi) = self.find_flag_long(arg) {
            self.check_help_version_long(arg)?;
            matcher.inc(self.flags[fi].name);
            return Ok(ParseResult::Flag);
        }
        // did you mean
        let longs: Vec<&str> = self
            .flags
            .iter()
            .filter_map(|f| f.long)
            .chain(self.opts.iter().filter_map(|o| o.long))
            .collect();
        let mut suffix = String::new();
        let mut cand_name: Option<&str> = None;
        if let Some(c) = did_you_mean(arg, longs.iter().copied()) {
            suffix = format!("\n\tDid you mean {}{}?", good("--"), good(c));
            cand_name = Some(c);
        } else {
            let mut best: Option<(usize, String)> = None;
            for sc in &self.subcommands {
                let opts: Vec<&str> = sc
                    .flags
                    .iter()
                    .filter_map(|f| f.long)
                    .chain(sc.opts.iter().filter_map(|o| o.long))
                    .collect();
                if let Some(c) = did_you_mean(arg, opts.iter().copied()) {
                    if let Some(score) = rest.iter().position(|x| x == sc.name) {
                        let s = format!(
                            "\n\tDid you mean to put '{}{}' after the subcommand '{}'?",
                            good("--"),
                            good(c),
                            good(sc.name)
                        );
                        if best.as_ref().map_or(true, |b| score < b.0) {
                            best = Some((score, s));
                        }
                    }
                }
            }
            if let Some((_, s)) = best {
                suffix = s;
            }
        }
        if let Some(c) = cand_name {
            if let Some(oi) = self.find_opt_long(c) {
                matcher.insert(self.opts[oi].name);
            } else if let Some(fi) = self.find_flag_long(c) {
                matcher.insert(self.flags[fi].name);
            }
        }
        Err(self.unknown_argument(&format!("--{}", arg), &suffix, matcher))
    }

    fn parse_short_arg(&self, matcher: &mut Matches, full_arg: &str) -> Result<ParseResult, ClapError> {
        let arg = full_arg.trim_start_matches('-');
        let mut ret = ParseResult::NotFound;
        for (ci, c) in arg.char_indices() {
            if let Some(oi) = self.find_opt_short(c) {
                let after = &arg[ci + c.len_utf8()..];
                let val = if !after.is_empty() { Some(after) } else { None };
                return self.parse_opt(val, oi, matcher);
            } else if let Some(fi) = self.find_flag_short(c) {
                if self.help_short && c == 'h' {
                    return Err(ClapError::Help(self.help_text()));
                }
                if c == 'V' {
                    return Err(ClapError::Version(self.version_text()));
                }
                matcher.inc(self.flags[fi].name);
                ret = ParseResult::Flag;
            } else {
                return Err(self.unknown_argument(&format!("-{}", c), "", matcher));
            }
        }
        Ok(ret)
    }

    fn parse_help_subcommand(&self, rest: &[String]) -> ClapError {
        let mut help_help = false;
        let mut bin_name = self.bin_name.clone();
        let mut sc: AppDef = self.clone();
        for cmd in rest {
            if cmd == "help" {
                help_help = true;
            }
            if let Some(c) = sc.subcommands.iter().find(|s| s.name == cmd) {
                let c = c.clone();
                sc = c;
                bin_name = format!("{} {}", bin_name, sc.name);
            } else if cmd == "help" && !sc.subcommands.is_empty() {
                sc = help_app();
                bin_name = format!("{} {}", bin_name, sc.name);
            } else {
                return ClapError::Error(format!(
                    "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
                    cmd, self.bin_name
                ));
            }
        }
        let _ = help_help;
        if sc.bin_name != self.bin_name || rest.len() > 0 {
            sc.bin_name = bin_name;
            sc.usage = None;
        }
        ClapError::Help(sc.help_text())
    }

    pub fn get_matches(&mut self, args: &[String]) -> Result<Matches, ClapError> {
        let mut matcher = Matches::default();
        let mut needs_val_of = ParseResult::NotFound;
        let mut trailing = false;
        let mut subcmd: Option<usize> = None;
        let mut pos_counter = 0usize;
        let mut i = 0usize;
        while i < args.len() {
            let arg = args[i].clone();
            i += 1;
            let starts_new_arg = match needs_val_of {
                ParseResult::ValuesDone => true,
                _ => {
                    if arg.starts_with("--") {
                        true
                    } else if arg.starts_with('-') {
                        arg.len() != 1
                    } else {
                        false
                    }
                }
            };
            if !trailing {
                match needs_val_of {
                    ParseResult::Opt(_) => {}
                    _ => {
                        if arg == "help" && !self.subcommands.is_empty() {
                            return Err(self.parse_help_subcommand(&args[i..]));
                        }
                        if let Some(si) = self.subcommands.iter().position(|s| s.name == arg) {
                            subcmd = Some(si);
                            break;
                        }
                    }
                }
                if starts_new_arg {
                    if arg == "--" {
                        trailing = true;
                        needs_val_of = ParseResult::NotFound;
                        continue;
                    } else if arg.starts_with("--") {
                        needs_val_of = self.parse_long_arg(&mut matcher, &arg, &args[i..])?;
                        continue;
                    } else if arg.starts_with('-') && arg.len() != 1 {
                        needs_val_of = self.parse_short_arg(&mut matcher, &arg)?;
                        continue;
                    }
                } else if let ParseResult::Opt(oi) = needs_val_of {
                    let name = self.opts[oi].name;
                    matcher.add_val(name, &arg);
                    needs_val_of = ParseResult::ValuesDone;
                    continue;
                }
            }
            // positional
            let names = self.sc_names();
            if let Some(c) = did_you_mean(&arg, names.iter().copied()) {
                return Err(ClapError::Error(format!(
                    "error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\n{}\n\nFor more information try --help\n",
                    arg,
                    c,
                    self.bin_name,
                    arg,
                    self.error_usage(&matcher)
                )));
            }
            if pos_counter < self.positionals.len() {
                let p = self.positionals[pos_counter].clone();
                matcher.add_val(p.name, &arg);
                matcher.inc(p.name);
                if !p.multiple {
                    pos_counter += 1;
                }
            } else {
                return Err(self.unknown_argument(&arg, "", &matcher));
            }
        }

        if let Some(si) = subcmd {
            // mid string: required args of the parent not yet given
            let mut hs: Vec<String> = self.required_names().iter().map(|s| s.to_string()).collect();
            for n in &matcher.order {
                hs.push(n.clone());
            }
            let reqs = self.required_usage_from(&hs, Some(&matcher));
            let mut mid = String::new();
            for s in &reqs {
                mid.push(' ');
                mid.push_str(s);
            }
            mid.push(' ');
            let parent_bin = self.bin_name.clone();
            let sc = &mut self.subcommands[si];
            sc.usage = Some(format!("{}{}{}", parent_bin, mid, sc.name));
            sc.bin_name = format!("{} {}", parent_bin, sc.name);
            let sub_matches = sc.get_matches(&args[i..])?;
            let sc_name = sc.name.to_string();
            matcher.subcommand = Some((sc_name, Box::new(sub_matches)));
        }

        // validation
        let mut reqs_validated = false;
        if let ParseResult::Opt(oi) = needs_val_of {
            self.validate_required(&matcher)?;
            reqs_validated = true;
            let o = &self.opts[oi];
            let should_err = match matcher.args.get(o.name) {
                Some(m) => m.vals.is_empty(),
                None => true,
            };
            if should_err {
                return Err(ClapError::Error(format!(
                    "error: The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try --help\n",
                    self.arg_display(o.name).unwrap(),
                    self.error_usage(&matcher)
                )));
            }
        }
        if !reqs_validated {
            self.validate_required(&matcher)?;
        }
        // occurrences
        for n in &matcher.order {
            let m = &matcher.args[n];
            let multiple = self
                .positionals
                .iter()
                .any(|p| p.name == n && p.multiple);
            if m.occurs > 1 && !multiple {
                return Err(ClapError::Error(format!(
                    "error: The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try --help\n",
                    self.arg_display(n).unwrap(),
                    self.error_usage(&matcher)
                )));
            }
        }
        Ok(matcher)
    }

    fn validate_required(&self, matcher: &Matches) -> Result<(), ClapError> {
        let reqs: Vec<String> = self.required_names().iter().map(|s| s.to_string()).collect();
        let missing: Vec<&String> = reqs.iter().filter(|r| !matcher.contains(r)).collect();
        if missing.is_empty() {
            return Ok(());
        }
        let list = self.required_usage_from(&reqs, Some(matcher));
        let mut s = String::new();
        for l in list {
            s.push_str("\n    ");
            s.push_str(&l);
        }
        Err(ClapError::Error(format!(
            "error: The following required arguments were not provided:{}\n\n{}\n\nFor more information try --help\n",
            s,
            self.error_usage(matcher)
        )))
    }
}

