mod cli;
mod geometry;
mod inputs;
mod obj;
mod output;
mod panics;
mod render;
mod stl;
mod terminal;

use std::io::Write;

#[derive(Debug)]
pub enum ErrorKind {
    IoError(std::io::Error),
}

impl std::fmt::Display for ErrorKind {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            ErrorKind::IoError(e) => write!(f, "{}", e),
        }
    }
}

impl std::error::Error for ErrorKind {}

fn write_stdout(s: &str) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(s.as_bytes());
    let _ = lock.flush();
}

fn run(m: &cli::Matches) -> Result<(), Box<dyn std::error::Error>> {
    let input = m.value_of("input filename(s)").unwrap_or("");
    let meshes = inputs::load_meshes(input);
    let nocolor = m.is_present("nocolor");
    let x: f32 = m.value_of("x").unwrap_or("0").parse()?;
    let y: f32 = m.value_of("y").unwrap_or("0").parse()?;
    let z: f32 = m.value_of("z").unwrap_or("0").parse()?;

    if let Some(sub) = m.subcommand_matches("image") {
        let width: usize = sub.value_of("width").unwrap_or("").parse()?;
        let height: usize = match sub.value_of("height") {
            Some(h) => h.parse()?,
            None => width,
        };
        let ix: f32 = sub.value_of("x").unwrap_or("0").parse()?;
        let iy: f32 = sub.value_of("y").unwrap_or("0").parse()?;
        let iz: f32 = sub.value_of("z").unwrap_or("0").parse()?;
        let frames: Option<usize> = match sub.value_of("frame count") {
            Some(j) => Some(j.parse()?),
            None => None,
        };
        match frames {
            None => {
                let mut frame = render::Frame::new(width, height, true);
                render::render(&meshes, &mut frame, ix, iy, iz);
                if nocolor {
                    let mut s = output::plain_cells(&frame.cells);
                    s.push('\n');
                    write_stdout(&s);
                } else {
                    write_stdout(&output::color_cells(&frame.cells));
                }
            }
            Some(n) => {
                let count = n.max(1);
                let mut out = String::from("let frames = [\n");
                for i in 0..count {
                    let angle = render::webify_angle(i, n);
                    let mut frame = render::Frame::new(width, height, true);
                    render::render(&meshes, &mut frame, ix, iy + angle, iz);
                    out.push_str("`\n");
                    if nocolor {
                        out.push_str(&output::plain_cells(&frame.cells));
                        out.push('\n');
                    } else {
                        out.push_str(&output::html_cells(&frame.cells));
                    }
                    out.push('`');
                    if i + 1 < count {
                        out.push_str(",\n");
                    }
                }
                out.push_str("];\n");
                write_stdout(&out);
            }
        }
        return Ok(());
    }

    terminal::run(&meshes, x, y, z, nocolor).map_err(|e| Box::new(ErrorKind::IoError(e)) as Box<dyn std::error::Error>)
}

fn main() {
    panics::install_hook();
    let args: Vec<String> = std::env::args_os()
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let bin_name = args
        .get(0)
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "sloth".to_string());
    let mut app = cli::build_app(&bin_name);
    let rest: Vec<String> = args.iter().skip(1).cloned().collect();
