// Formatting of rendered frames.

use crate::render::Cell;

pub fn color_cells(cells: &[Cell]) -> String {
    let mut out = String::with_capacity(cells.len() * 40);
    for c in cells {
        out.push_str("\x1b[48;2;25;25;25m\x1b[38;2;");
        push_rgb(&mut out, c.color, ';');
        out.push('m');
        out.push(c.ch);
        out.push_str("\x1b[49m\x1b[39m");
    }
    out
}

pub fn plain_cells(cells: &[Cell]) -> String {
    let mut out = String::with_capacity(cells.len() + 1);
    for c in cells {
        out.push(c.ch);
    }
    out
}

pub fn html_cells(cells: &[Cell]) -> String {
    let mut out = String::with_capacity(cells.len() * 36);
    for c in cells {
        out.push_str("<span style=\"color:rgb(");
        push_rgb(&mut out, c.color, ',');
        out.push_str(")\">");
        out.push(c.ch);
    }
    out
}

fn push_rgb(out: &mut String, c: [u8; 3], sep: char) {
    out.push_str(&c[0].to_string());
    out.push(sep);
    out.push_str(&c[1].to_string());
    out.push(sep);
    out.push_str(&c[2].to_string());
}
