}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: i32, t: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, act: i32, t: *const Termios) -> i32;
    fn cfmakeraw(t: *mut Termios);
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn poll(fds: *mut PollFd, n: u64, timeout: i32) -> i32;
    fn read(fd: i32, buf: *mut u8, n: usize) -> isize;
}

const TIOCGWINSZ: u64 = 0x5413;
const TCSANOW: i32 = 0;
const POLLIN: i16 = 1;

fn get_attr(fd: i32) -> io::Result<Termios> {
    let mut t = Termios {
        c_iflag: 0,
        c_oflag: 0,
        c_cflag: 0,
        c_lflag: 0,
        c_line: 0,
        c_cc: [0; 32],
        c_ispeed: 0,
        c_ospeed: 0,
    };
    if unsafe { tcgetattr(fd, &mut t) } == -1 {
        return Err(io::Error::last_os_error());
    }
    Ok(t)
}

fn set_attr(fd: i32, t: &Termios) -> io::Result<()> {
    if unsafe { tcsetattr(fd, TCSANOW, t) } == -1 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn win_size(fd: i32) -> Option<(u16, u16)> {
    let mut ws = Winsize::default();
    if unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) } == -1 {
        return None;
    }
    Some((ws.ws_col, ws.ws_row))
}

fn size() -> io::Result<(u16, u16)> {
    if let Some(s) = win_size(1) {
        return Ok(s);
    }
    if let Some(s) = win_size(0) {
        return Ok(s);
    }
    if let Some(s) = win_size(2) {
        return Ok(s);
    }
    Err(io::Error::last_os_error())
}

/// Returns true when the user asked to quit.
fn poll_quit() -> io::Result<bool> {
    let mut quit = false;
    loop {
        let mut fds = PollFd {
            fd: 0,
            events: POLLIN,
            revents: 0,
        };
        let r = unsafe { poll(&mut fds, 1, 0) };
        if r <= 0 || (fds.revents & POLLIN) == 0 {
            break;
        }
        let mut buf = [0u8; 64];
        let n = unsafe { read(0, buf.as_mut_ptr(), buf.len()) };
        if n <= 0 {
            break;
        }
        for &b in &buf[..n as usize] {
            if b == b'q' || b == 3 {
                quit = true;
            }
        }
    }
    Ok(quit)
}

pub fn run(meshes: &[SimpleMesh], x: f32, y: f32, z: f32, nocolor: bool) -> io::Result<()> {
    let original = get_attr(0)?;
    let mut raw = original;
    unsafe { cfmakeraw(&mut raw) };
    set_attr(0, &raw)?;

    let stdout = io::stdout();
    let result = (|| -> io::Result<()> {
        {
            let mut out = stdout.lock();
            out.write_all(b"\x1b[?25l")?;
            out.flush()?;
        }
        let start = Instant::now();
        loop {
            let (w, h) = size()?;
            let mut frame = render::Frame::new(w as usize, h as usize, false);
            let t = start.elapsed().as_secs_f32();
            render::render(meshes, &mut frame, x, y + t, z);
            let body = if nocolor {
                output::plain_cells(&frame.cells)
            } else {
                output::color_cells(&frame.cells)
            };
            {
                let mut out = stdout.lock();
                out.write_all(b"\x1b[1;1H")?;
                out.write_all(body.as_bytes())?;
                out.flush()?;
            }
            if poll_quit()? {
                break;
            }
        }
        let mut out = stdout.lock();
        out.write_all(b"\x1b[?25h")?;
        out.flush()?;
        Ok(())
    })();
    let _ = set_attr(0, &original);
    result
}
