                    let e2 = edge(&sv[0], &sv[1], &pt);
                    if e0 <= 0.0 && e1 <= 0.0 && e2 <= 0.0 {
                        let w0 = e0 / area;
                        let w1 = e1 / area;
                        let w2 = e2 / area;
                        let z = w0 * sv[0][2] + w1 * sv[1][2] + w2 * sv[2][2];
                        let idx = x * 2 + y * w;
                        if idx + 1 >= len {
                            continue;
                        }
                        if z < frame.zbuf[idx] {
                            frame.zbuf[idx] = z;
                            let shade = intensity * ((e0 + e1 + e2) / area);
                            let ch = shade_char(shade);
                            frame.cells[idx] = Cell { ch, color };
                            frame.cells[idx + 1] = Cell { ch, color };
                        }
                    }
                }
                if frame.image_mode {
                    let idx = y * w + 1;
                    if idx < len {
                        frame.cells[idx] = Cell {
                            ch: '\n',
                            color: [0, 0, 0],
                        };
                    }
                }
            }
        }
    }
}
