sys.path.insert(0,'/tmp/exp')
pat=re.compile(r'<span style="color:rgb\((\d+),(\d+),(\d+)\)">(.)',re.S)
def run(args,w):
    a=subprocess.run(['/workspace/executable']+args,capture_output=True,text=True).stdout
    fa=[pat.findall(x) for x in a.split('`')[1::2]]
    env=dict(os.environ); env['DUMPALL']='1'
    b=subprocess.run(['/tmp/lab_sloth']+args,capture_output=True,text=True,env=env)
    frames=[]; cur=None
    for line in b.stderr.split('\n'):
        p=line.split()
        if not p: continue
        if p[0]=='MAT': cur={'mat':[float(t) for t in p[1:]],'pix':[]}; frames.append(cur)
        elif p[0]=='ALL': cur['pix'].append([int(p[1]),int(p[2])]+[float(t) for t in p[3:]])
    for i,fr in enumerate(frames):
        cells=fa[i]
        for px in fr['pix']:
            idx=2*px[0]+px[1]*w
            c=cells[idx]
            px.append([int(c[0]),int(c[1]),int(c[2]),c[3]])
    return frames
data=[]
for wh in [(80,40),(41,23),(100,58),(86,67),(118,45),(135,15)]:
    for n in ['4','8']:
        args=['/workspace/assets/test_model.obj','image','-w',str(wh[0]),'-h',str(wh[1]),'-j',n]
        data.extend(run(args,wh[0]))
json.dump(data,open('/tmp/exp/tmd.json','w'))
print(len(data), sum(len(f['pix']) for f in data))
EOF
